import argparse
import sys
import os


def create_parser():
    parser = argparse.ArgumentParser(description='Count lines, words, and characters in files.')
    parser.add_argument('files', nargs='+', help='Files to analyze')
    return parser


def count_file(filepath):
    """Reads a file and returns a tuple of (line_count, word_count, char_count)."""
    if not os.path.exists(filepath):
        print(f"Error: File '{filepath}' does not exist.", file=sys.stderr)
        return None

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()

        line_count = content.count('\n')
        # If the file ends with a newline, the last line is often counted as empty in some definitions,
        # but standard `wc` behavior usually counts lines as newline characters. 
        # Let's stick to standard wc behavior: lines = number of newline characters.
        # However, if the file is not empty and doesn't end in newline, it still has that last line.
        if content and not content.endswith('\n'):
            line_count += 1

        word_count = len(content.split())
        char_count = len(content)

        return (line_count, word_count, char_count)
    except Exception as e:
        print(f"Error reading file '{filepath}': {e}", file=sys.stderr)
        return None


def main():
    parser = create_parser()
    args = parser.parse_args()

    results = []
    has_error = False

    for filepath in args.files:
        counts = count_file(filepath)
        if counts is None:
            has_error = True
        else:
            results.append((filepath, *counts))

    if results:
        # Print header
        print(f"{'File':<20} {'Lines':>8} {'Words':>8} {'Chars':>8}")
        print('-' * 46)

        # Print rows
        for filepath, lines, words, chars in results:
            print(f"{filepath:<20} {lines:>8} {words:>8} {chars:>8}")

    if has_error:
        sys.exit(1)


if __name__ == '__main__':
    main()

