def scan_log(args):
    matching_lines = []
    try:
        with open(args.file_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()

        # Filter lines containing the specified level (case-insensitive)
        # We convert line to uppercase to match the normalized args.level
        for line in lines:
            if args.level in line.upper():
                matching_lines.append(line)

        # Reverse to get newest last (assuming last line in file is newest)
        matching_lines.reverse()

        # Apply limit if specified
        if args.limit is not None:
            matching_lines = matching_lines[:args.limit]

        # Print matching lines to stdout
        for line in matching_lines:
            print(line, end='')

        # Print count to stderr
        print(f"Count: {len(matching_lines)}", file=sys.stderr)

    except Exception as e:
        print(f"Error reading file: {e}", file=sys.stderr)
        sys.exit(1)
